import csv
import io
import json

_FIELDS = ("id", "name")


def _normalize(rows):
    for row in rows:
        yield {k: "" if row.get(k) is None else str(row[k]) for k in _FIELDS}


def _to_csv(rows):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(_FIELDS)
    for row in rows:
        writer.writerow([row[k] for k in _FIELDS])
    return buffer.getvalue()


def _to_json(rows):
    return json.dumps(list(rows), ensure_ascii=False, separators=(",", ":"))


_SERIALIZERS = {"csv": _to_csv, "json": _to_json}


def export_rows(rows, format):
    try:
        serializer = _SERIALIZERS[format]
    except (KeyError, TypeError):
        raise ValueError("unsupported format") from None
    return serializer(_normalize(rows))

